1	package remediation
2	
3	import (
4		"regexp"
5		"strings"
6	
7		"gopkg.in/yaml.v3"
8	
9		"github.com/anthnel/devdesk/internal/k8s"
10		"github.com/anthnel/devdesk/internal/patch"
11		"github.com/anthnel/devdesk/internal/scan"
12	)
13	
14	// Kubernetes manifests (§3.80). The same discipline as the Dockerfile rules:
15	// an edit that is exactly right or a decline, never an approximation. What is
16	// new is that a manifest is YAML, so a fix may have to add a key rather than
17	// change a token — and that is still a byte-range edit here, computed from
18	// yaml.v3's node positions, never a re-serialisation of the document, which
19	// would drop the author's comments and formatting.
20	//
21	// Three rules, and the ones left out were each left out for a reason:
22	//
23	//   - KSV-0017 (privileged) and KSV-0001 (allowPrivilegeEscalation) name the
24	//     exact field and value to set, and the ids were read from trivy-checks'
25	//     rego sources (checks/kubernetes/privileged.rego and
26	//     can_elevate_its_own_privileges.rego), not guessed.
27	//   - K8S-API-REMOVED is fixed only where the Kubernetes deprecation guide says
28	//     "No notable changes" — renaming the apiVersion is then the whole
29	//     migration. Where it lists changes (Ingress, HPA, PodDisruptionBudget,
30	//     the apps/v1 workloads, CRDs, webhooks…), a rename would produce a
31	//     manifest that validates and behaves differently.
32	//   - runAsNonRoot, readOnlyRootFilesystem and dropping ALL capabilities pass
33	//     their rule and can stop the container from starting: whether the image
34	//     runs as root, writes to its filesystem or needs a capability is not in
35	//     the manifest. It is the USER 1000 lesson of §3.78 — the re-scan would
36	//     approve a pod that no longer runs.
37	//   - Resource requests and limits have no universal value.
38	//   - A seccomp profile can be set at the pod or the container level, and
39	//     which one the author meant is not something the finding says.
40	
41	// The reasons the Kubernetes fixes decline.
42	const (
43		ReasonNotAManifest = "The catalog only fixes plain Kubernetes manifests — a Helm chart or a Kustomize overlay is fixed in its values, template or patch"
44		// ReasonContainerNotFound is a stale finding: the file no longer has the
45		// container it named, at the lines it named.
46		ReasonContainerNotFound = "The reported container is not at the reported lines of this file"
47		ReasonNotPlainBoolean   = "The value is not a plain true/false this fix can rewrite"
48		ReasonInlineMapping     = "This securityContext is written inline ({…}); the fix only edits block style"
49		ReasonNoInsertionPoint  = "No key of this container starts its own line, so there is nowhere to insert the setting"
50		ReasonNotPrivileged     = "The container is no longer privileged"
51		ReasonEscalationOff     = "The container already sets allowPrivilegeEscalation: false"
52		// ReasonPrivilegedContainer and ReasonSysAdmin are the API server's own
53		// validation: it refuses allowPrivilegeEscalation: false on a container
54		// that is privileged or adds CAP_SYS_ADMIN. The fix would pass Trivy's
55		// rule and produce a manifest nobody can apply.
56		ReasonPrivilegedContainer = "The container is privileged, and the API server refuses allowPrivilegeEscalation: false with it — fix KSV-0017 first"
57		ReasonSysAdmin            = "The container adds CAP_SYS_ADMIN, and the API server refuses allowPrivilegeEscalation: false with it"
58		// The host namespace fixes (DEVDESK-687).
59		ReasonHostFieldNotTrue = "The pod spec no longer sets this field to true"
60		ReasonSharedByAlias    = "This pod spec or value is shared through a YAML alias, so editing it would change every place that uses it"
61		ReasonAmbiguousField   = "This field cannot be located without ambiguity in the pod spec (duplicate or merged key)"
62		// ReasonWorkloadChanged is a stale host namespace finding: the workload or
63		// the lines at the reported position are not the ones the message names.
64		ReasonWorkloadChanged   = "The manifest changed since the scan: the workload at the reported lines is not the one the finding names, scan again"
65		ReasonNoSimpleMigration = "Moving this kind to a served apiVersion changes more than the apiVersion — see the Kubernetes deprecation guide"
66	)
67	
68	// workloadInMessage is how Trivy's pod-level rules name the workload they are
69	// about: "Pod 'all' should not set 'spec.template.spec.hostIPC' to true".
70	var workloadInMessage = regexp.MustCompile(`^(\w+) '([^']+)'`)
71	
72	// containerInMessage is how Trivy's KSV rules name the container they are
73	// about: "Container 'api' of Deployment 'web' should set …".
74	var containerInMessage = regexp.MustCompile(`Container '([^']+)'`)
75	
76	// renamedAPIs are the removals whose migration is the apiVersion alone:
77	// every entry is one the deprecation guide marks "No notable changes",
78	// checked against kubernetes/website on 2026-09-22. Keyed "apiVersion Kind".
79	var renamedAPIs = map[string]string{
80		"batch/v1beta1 CronJob":                                "batch/v1",
81		"storage.k8s.io/v1beta1 CSIStorageCapacity":            "storage.k8s.io/v1",
82		"node.k8s.io/v1beta1 RuntimeClass":                     "node.k8s.io/v1",
83		"apiregistration.k8s.io/v1beta1 APIService":            "apiregistration.k8s.io/v1",
84		"coordination.k8s.io/v1beta1 Lease":                    "coordination.k8s.io/v1",
85		"networking.k8s.io/v1beta1 IngressClass":               "networking.k8s.io/v1",
86		"rbac.authorization.k8s.io/v1beta1 ClusterRole":        "rbac.authorization.k8s.io/v1",
87		"rbac.authorization.k8s.io/v1beta1 ClusterRoleBinding": "rbac.authorization.k8s.io/v1",
88		"rbac.authorization.k8s.io/v1beta1 Role":               "rbac.authorization.k8s.io/v1",
89		"rbac.authorization.k8s.io/v1beta1 RoleBinding":        "rbac.authorization.k8s.io/v1",
90		"scheduling.k8s.io/v1beta1 PriorityClass":              "scheduling.k8s.io/v1",
91		"storage.k8s.io/v1beta1 CSIDriver":                     "storage.k8s.io/v1",
92		"storage.k8s.io/v1beta1 CSINode":                       "storage.k8s.io/v1",
93		"storage.k8s.io/v1beta1 StorageClass":                  "storage.k8s.io/v1",
94		"storage.k8s.io/v1beta1 VolumeAttachment":              "storage.k8s.io/v1",
95	}
96	
97	// plainManifest refuses a finding that is not about a file of plain YAML.
98	func plainManifest(f scan.Finding) string {
99		if f.IaCType != "kubernetes" {
100			return ReasonNotAManifest
101		}
102		return ""
103	}
104	
105	// fixPrivileged satisfies KSV-0017 by turning privileged: true into false.
106	// The key exists — that is what the rule fired on — so this is a token swap.
107	func fixPrivileged(content []byte, f scan.Finding) ([]patch.Edit, string) {
108		c, reason := reportedContainer(content, f)
109		if reason != "" {
110			return nil, reason
111		}
112		_, sc, _ := k8s.Entry(c, "securityContext")
113		var value *yaml.Node
114		if sc != nil {
115			_, value, _ = k8s.Entry(sc, "privileged")
116		}
117		if value == nil || value.Value == "false" {
118			return nil, ReasonNotPrivileged
119		}
120		return swapBoolean(content, value)
121	}
122	
123	// fixPrivilegeEscalation satisfies KSV-0001: allowPrivilegeEscalation: false on
124	// the container Trivy named. The rule fires on a value of true and on no value
125	// at all, so this is either a swap or an insertion, and an insertion goes
126	// above an existing key, at that key's indentation.
127	func fixPrivilegeEscalation(content []byte, f scan.Finding) ([]patch.Edit, string) {
128		c, reason := reportedContainer(content, f)
129		if reason != "" {
130			return nil, reason
131		}
132		_, sc, hasContext := k8s.Entry(c, "securityContext")
133		if hasContext {
134			if reason := escalationRefused(sc); reason != "" {
135				return nil, reason
136			}
137			if _, value, ok := k8s.Entry(sc, "allowPrivilegeEscalation"); ok {
138				if value.Value == "false" {
139					return nil, ReasonEscalationOff
140				}
141				return swapBoolean(content, value)
142			}
143			if sc.Kind != yaml.MappingNode || sc.Style&yaml.FlowStyle != 0 || len(sc.Content) == 0 {
144				return nil, ReasonInlineMapping
145			}
146			return insertAbove(content, sc.Content[0], "allowPrivilegeEscalation: false")
147		}
148		for i := 0; i < len(c.Content); i += 2 {
149			if _, _, ok := k8s.OwnLineIndent(content, c.Content[i]); ok {
150				nl := k8s.LineEnding(content)
151				return insertAbove(content, c.Content[i], "securityContext:"+nl+"{indent}  allowPrivilegeEscalation: false")
152			}
153		}
154		return nil, ReasonNoInsertionPoint
155	}
156	
157	// escalationRefused is the API server's validation of a securityContext that
158	// would carry allowPrivilegeEscalation: false.
159	func escalationRefused(sc *yaml.Node) string {
160		if k8s.Scalar(sc, "privileged") == "true" {
161			return ReasonPrivilegedContainer
162		}
163		if _, caps, ok := k8s.Entry(sc, "capabilities"); ok {
164			if _, add, ok := k8s.Entry(caps, "add"); ok {
165				for _, c := range add.Content {
166					if name := strings.TrimPrefix(strings.ToUpper(c.Value), "CAP_"); name == "SYS_ADMIN" {
167						return ReasonSysAdmin
168					}
169				}
170			}
171		}
172		return ""
173	}
174	
175	// fixRemovedAPI satisfies K8S-API-REMOVED by renaming the apiVersion, for the
176	// kinds where that is the entire migration.
177	func fixRemovedAPI(content []byte, f scan.Finding) ([]patch.Edit, string) {
178		if reason := plainManifest(f); reason != "" {
179			return nil, reason
180		}
181		doc, ok := k8s.DocumentAt(content, f.Line)
182		if !ok {
183			return nil, ReasonUnreadableSpan
184		}
185		_, version, ok := k8s.Entry(doc, "apiVersion")
186		if !ok {
187			return nil, ReasonUnreadableSpan
188		}
189		target, ok := renamedAPIs[version.Value+" "+k8s.Scalar(doc, "kind")]
190		if !ok {
191			return nil, ReasonNoSimpleMigration
192		}
193		start, end, ok := k8s.PlainScalarSpan(content, version)
194		if !ok {
195			return nil, ReasonUnreadableSpan
196		}
197		return []patch.Edit{{Span: patch.Span{Start: start, End: end}, Old: version.Value, New: target}}, ""
198	}
199	
200	// reportedContainer finds the container a KSV finding is about: in the
201	// document holding the reported line, by the name Trivy's message gives. A
202	// finding whose file no longer matches is declined rather than applied to
203	// whatever sits there now.
204	func reportedContainer(content []byte, f scan.Finding) (*yaml.Node, string) {
205		if reason := plainManifest(f); reason != "" {
206			return nil, reason
207		}
208		m := containerInMessage.FindStringSubmatch(f.Message)
209		if m == nil || f.Line <= 0 {
210			return nil, ReasonUnreadableSpan
211		}
212		doc, ok := k8s.DocumentAt(content, f.Line)
213		if !ok {
214			return nil, ReasonUnreadableSpan
215		}
216		for _, c := range k8s.Containers(doc) {
217			if k8s.Scalar(c, "name") != m[1] {
218				continue
219			}
220			if f.EndLine > 0 && (c.Line < f.Line || c.Line > f.EndLine) {
221				continue
222			}
223			return c, ""
224		}
225		return nil, ReasonContainerNotFound
226	}
227	
228	// swapBoolean replaces a plain true with false.
229	func swapBoolean(content []byte, value *yaml.Node) ([]patch.Edit, string) {
230		if value.Value != "true" {
231			return nil, ReasonNotPlainBoolean
232		}
233		start, end, ok := k8s.PlainScalarSpan(content, value)
234		if !ok {
235			return nil, ReasonNotPlainBoolean
236		}
237		return []patch.Edit{{Span: patch.Span{Start: start, End: end}, Old: value.Value, New: "false"}}, ""
238	}
239	
240	// insertAbove adds text as new lines above key, at key's indentation. A
241	// "{indent}" in text stands for that indentation on the lines after the first.
242	func insertAbove(content []byte, key *yaml.Node, text string) ([]patch.Edit, string) {
243		lineStart, indent, ok := k8s.OwnLineIndent(content, key)
244		if !ok {
245			return nil, ReasonNoInsertionPoint
246		}
247		text = strings.ReplaceAll(text, "{indent}", indent)
248		return []patch.Edit{{
249			Span: patch.Span{Start: lineStart, End: lineStart},
250			New:  indent + text + k8s.LineEnding(content),
251		}}, ""
252	}
253	
254	// fixHostNamespace is the fix of hostNetwork, hostPID and hostIPC: set the
255	// field of the pod spec to false (DEVDESK-687). The finding is about the pod,
256	// not a container, and Trivy words its path as spec.template.spec.<field> even
257	// for a Pod, so the pod spec comes from the workload's kind, not from the
258	// message.
259	func fixHostNamespace(field string) func([]byte, scan.Finding) ([]patch.Edit, string) {
260		return func(content []byte, f scan.Finding) ([]patch.Edit, string) {
261			value, reason := podSpecFlag(content, f, field)
262			if reason != "" {
263				return nil, reason
264			}
265			if value.Kind == yaml.ScalarNode && value.Style == 0 && value.Value == "false" {
266				return nil, ReasonHostFieldNotTrue
267			}
268			return swapBoolean(content, value)
269		}
270	}
271	
272	// podSpecFlag finds the value node of field in the pod spec of the workload
273	// the finding is in, or says why it cannot be located exactly. It declines a
274	// pod spec or a value that other places share (a YAML alias, or an anchor
275	// something else points at: the edit would change them too), a key written
276	// twice or reached through a merge key (which of them is in force is not for
277	// this fix to decide), and a field the pod spec does not set. The value is
278	// returned as written, so the caller still sees a quoted or tagged scalar.
279	func podSpecFlag(content []byte, f scan.Finding, field string) (*yaml.Node, string) {
280		if reason := plainManifest(f); reason != "" {
281			return nil, reason
282		}
283		if f.Line <= 0 {
284			return nil, ReasonUnreadableSpan
285		}
286		doc, ok := k8s.DocumentAt(content, f.Line)
287		if !ok {
288			return nil, ReasonUnreadableSpan
289		}
290		specs := k8s.PodSpecs(doc)
291		if len(specs) != 1 {
292			return nil, ReasonUnreadableSpan
293		}
294		spec := specs[0].Spec
295		if !namesWorkload(doc, spec, f) {
296			return nil, ReasonWorkloadChanged
297		}
298		if isShared(doc, spec) {
299			return nil, ReasonSharedByAlias
300		}
301		var value *yaml.Node
302		merged := false
303		for i := 0; i+1 < len(spec.Content); i += 2 {
304			key := spec.Content[i]
305			switch {
306			case key.Kind == yaml.AliasNode:
307				return nil, ReasonAmbiguousField
308			case key.Tag == "!!merge":
309				merged = true
310			case key.Value == field:
311				if value != nil {
312					return nil, ReasonAmbiguousField
313				}
314				value = spec.Content[i+1]
315			}
316		}
317		switch {
318		case value == nil && merged:
319			return nil, ReasonAmbiguousField
320		case value == nil:
321			return nil, ReasonHostFieldNotTrue
322		case value.Kind == yaml.AliasNode || isShared(doc, value):
323			return nil, ReasonSharedByAlias
324		}
325		return value, ""
326	}
327	
328	// namesWorkload reports whether doc is the workload Trivy's message names (kind
329	// and metadata.name) and its pod spec starts inside the lines the finding
330	// reported: the file may have changed since the scan, and the line alone then
331	// points at whatever sits there now. A message that names no workload gives
332	// nothing to compare, so it is refused rather than trusted.
333	func namesWorkload(doc, spec *yaml.Node, f scan.Finding) bool {
334		m := workloadInMessage.FindStringSubmatch(f.Message)
335		if m == nil || k8s.Scalar(doc, "kind") != m[1] {
336			return false
337		}
338		_, meta, ok := k8s.Entry(doc, "metadata")
339		if !ok || k8s.Scalar(meta, "name") != m[2] {
340			return false
341		}
342		return spec.Line >= f.Line && (f.EndLine <= 0 || spec.Line <= f.EndLine)
343	}
344	
345	// isShared reports whether an alias in doc points at n or at a node that
346	// contains it: editing n then changes what that alias stands for too.
347	func isShared(doc, n *yaml.Node) bool {
348		shared := false
349		var walk func(*yaml.Node)
350		walk = func(cur *yaml.Node) {
351			if shared {
352				return
353			}
354			if cur.Kind == yaml.AliasNode {
355				shared = cur.Alias != nil && contains(cur.Alias, n)
356				return
357			}
358			for _, c := range cur.Content {
359				walk(c)
360			}
361		}
362		walk(doc)
363		return shared
364	}
365	
366	// contains reports whether n is root or sits below it, without following aliases.
367	func contains(root, n *yaml.Node) bool {
368		if root == n {
369			return true
370		}
371		for _, c := range root.Content {
372			if c.Kind != yaml.AliasNode && contains(c, n) {
373				return true
374			}
375		}
376		return false
377	}
