1	package k8s
2	
3	import (
4		"bytes"
5		"errors"
6		"io"
7		"strconv"
8		"strings"
9	
10		"gopkg.in/yaml.v3"
11	)
12	
13	// Span is where a node sits in a file, 1-based and inclusive.
14	type Span struct {
15		Line    int
16		EndLine int
17	}
18	
19	// Locate finds the document of a multi-document file whose kind and
20	// metadata.name match, then follows a JSON pointer ("/spec/template/spec/
21	// containers/0") down into it.
22	//
23	// kubeconform reports a validation error by pointer and never by line, and a
24	// finding without a line is one nobody can jump to or fix. This is what turns
25	// the one into the other, by reading the file rather than by guessing: when a
26	// step of the pointer does not exist, the answer is not found, never the
27	// nearest line that does.
28	//
29	// The Line of a mapping entry is its key's — for a nested mapping the value
30	// starts on the next line, and the key is what a reader looks for. EndLine is
31	// the last line of the value.
32	//
33	// An empty name matches the first document of that kind, which is what a
34	// resource without metadata.name amounts to.
35	func Locate(content []byte, kind, name, pointer string) (Span, bool) {
36		doc, ok := findDocument(content, kind, name)
37		if !ok {
38			return Span{}, false
39		}
40		node, keyLine := doc, doc.Line
41		for _, seg := range splitPointer(pointer) {
42			node = resolveAlias(node)
43			switch node.Kind {
44			case yaml.MappingNode:
45				key, value, found := mappingEntry(node, seg)
46				if !found {
47					return Span{}, false
48				}
49				node, keyLine = value, key.Line
50			case yaml.SequenceNode:
51				i, err := strconv.Atoi(seg)
52				if err != nil || i < 0 || i >= len(node.Content) {
53					return Span{}, false
54				}
55				node = node.Content[i]
56				keyLine = node.Line
57			default:
58				return Span{}, false
59			}
60		}
61		return Span{Line: keyLine, EndLine: max(lastLine(node), keyLine)}, true
62	}
63	
64	// findDocument returns the top-level mapping of the matching document.
65	func findDocument(content []byte, kind, name string) (*yaml.Node, bool) {
66		dec := yaml.NewDecoder(bytes.NewReader(content))
67		for {
68			var doc yaml.Node
69			err := dec.Decode(&doc)
70			if errors.Is(err, io.EOF) || err != nil {
71				return nil, false
72			}
73			if doc.Kind != yaml.DocumentNode || len(doc.Content) == 0 {
74				continue
75			}
76			root := doc.Content[0]
77			if root.Kind != yaml.MappingNode || scalarAt(root, "kind") != kind {
78				continue
79			}
80			if name == "" {
81				return root, true
82			}
83			if _, meta, ok := mappingEntry(root, "metadata"); ok && scalarAt(resolveAlias(meta), "name") == name {
84				return root, true
85			}
86		}
87	}
88	
89	// DocumentField returns the span of one top-level key of the matching
90	// document — its apiVersion line, typically.
91	func DocumentField(content []byte, kind, name, key string) (Span, bool) {
92		return Locate(content, kind, name, "/"+key)
93	}
94	
95	func mappingEntry(m *yaml.Node, key string) (*yaml.Node, *yaml.Node, bool) {
96		for i := 0; i+1 < len(m.Content); i += 2 {
97			if m.Content[i].Value == key {
98				return m.Content[i], m.Content[i+1], true
99			}
100		}
101		return nil, nil, false
102	}
103	
104	func scalarAt(m *yaml.Node, key string) string {
