18	// DocumentIndex holds the top-level mappings of a manifest, decoded once, so a
19	// caller with many lines to place (one finding each) does not decode the file
20	// again for every one.
21	type DocumentIndex struct {
22		roots []*yaml.Node
23		last  []int
24	}
25	
26	// IndexDocuments decodes content once. Like DocumentAt it stops at the first
27	// decode error, keeping the documents read before it, and ignores documents
28	// that are not a mapping.
29	func IndexDocuments(content []byte) *DocumentIndex {
30		index := &DocumentIndex{}
31		dec := yaml.NewDecoder(bytes.NewReader(content))
32		for {
33			var doc yaml.Node
34			if err := dec.Decode(&doc); err != nil {
35				return index
36			}
37			if doc.Kind != yaml.DocumentNode || len(doc.Content) == 0 {
38				continue
39			}
40			if root := doc.Content[0]; root.Kind == yaml.MappingNode {
41				index.roots = append(index.roots, root)
42				index.last = append(index.last, lastLine(root))
43			}
44		}
45	}
46	
47	// At returns the top-level mapping of the document that holds line.
48	func (d *DocumentIndex) At(line int) (*yaml.Node, bool) {
49		for i, root := range d.roots {
50			if root.Line <= line && line <= d.last[i] {
51				return root, true
52			}
53		}
54		return nil, false
55	}
