57	// DocumentAt returns the top-level mapping of the document that holds line,
58	// decoding only as far as it.
59	func DocumentAt(content []byte, line int) (*yaml.Node, bool) {
60		dec := yaml.NewDecoder(bytes.NewReader(content))
61		for {
62			var doc yaml.Node
63			err := dec.Decode(&doc)
64			if errors.Is(err, io.EOF) || err != nil {
65				return nil, false
66			}
67			if doc.Kind != yaml.DocumentNode || len(doc.Content) == 0 {
68				continue
69			}
70			root := doc.Content[0]
71			if root.Kind == yaml.MappingNode && root.Line <= line && line <= lastLine(root) {
72				return root, true
73			}
74		}
75	}
