77	// Containers returns every container mapping of a workload, wherever its pod
78	// template sits — spec.containers for a Pod, spec.template.spec for a
79	// Deployment, spec.jobTemplate.spec.template.spec for a CronJob — along with
80	// init and ephemeral containers.
81	func Containers(doc *yaml.Node) []*yaml.Node {
82		var out []*yaml.Node
83		var walk func(n *yaml.Node)
84		walk = func(n *yaml.Node) {
85			n = resolveAlias(n)
