124	// Offset turns a node's line and column into a byte offset. yaml.v3 counts
125	// columns in characters, so the line is walked rune by rune.
126	func Offset(content []byte, line, column int) (int, bool) {
127		start, ok := LineStart(content, line)
128		if !ok {
129			return 0, false
130		}
131		at := start
132		for c := 1; c < column; c++ {
133			if at >= len(content) || content[at] == '\n' {
134				return 0, false
135			}
136			_, size := utf8.DecodeRune(content[at:])
137			at += size
138		}
139		return at, true
140	}
