142	// LineStart is the byte offset where a 1-based line begins.
143	func LineStart(content []byte, line int) (int, bool) {
144		if line < 1 {
145			return 0, false
146		}
147		at := 0
148		for l := 1; l < line; l++ {
149			i := bytes.IndexByte(content[at:], '\n')
150			if i < 0 {
151				return 0, false
152			}
153			at += i + 1
154		}
155		return at, true
156	}
