158	// LineEnding is the file's own line ending, so an inserted line does not mix
159	// "\n" into a CRLF file.
160	func LineEnding(content []byte) string {
161		if bytes.Contains(content, []byte("\r\n")) {
162			return "\r\n"
163		}
164		return "\n"
165	}
