167	// PlainScalarSpan is where a plain (unquoted) scalar's text sits in content.
168	// A quoted or block scalar is refused: its bytes are not its value, and an
169	// edit computed from the value would cut the quoting in half.
170	func PlainScalarSpan(content []byte, n *yaml.Node) (int, int, bool) {
171		if n == nil || n.Kind != yaml.ScalarNode || n.Style != 0 {
172			return 0, 0, false
173		}
174		start, ok := Offset(content, n.Line, n.Column)
