181	// OwnLineIndent returns the indentation before a node when the node is the
182	// first thing on its line — a key a new sibling can be inserted above. A key
183	// that follows "- " on a sequence item's line is not: inserting above it
184	// would land outside the item.
185	func OwnLineIndent(content []byte, n *yaml.Node) (lineStart int, indent string, ok bool) {
186		lineStart, ok = LineStart(content, n.Line)
187		if !ok {
188			return 0, "", false
189		}
190		at, ok := Offset(content, n.Line, n.Column)
191		if !ok {
192			return 0, "", false
193		}
194		prefix := content[lineStart:at]
195		if len(bytes.Trim(prefix, " ")) != 0 {
196			return 0, "", false
197		}
198		return lineStart, string(prefix), true
199	}
