183	// errDeclined carries a catalog refusal through the same channel as a failure,
184	// so the handler has one message to read, and tells the two apart by type rather
185	// than by inspecting a string.
186	type errDeclined struct{ reason string }
187	
188	func (e errDeclined) Error() string { return e.reason }
189	
190	// ── Confirming and writing ───────────────────────────────────────────────────
191	
192	func (m Model) handleMisconfigFixPrepared(msg MisconfigFixPreparedMsg) (tea.Model, tea.Cmd) {
193		if msg.Target != m.targetPath {
194			return m, nil // an answer about a result no longer on screen
195		}
196		if d, ok := msg.Err.(errDeclined); ok {
197			// Nothing failed: the catalog will not fix this instance, and says why.
198			return m, m.footer.Warn(d.reason)
199		}
200		if msg.Err != nil {
201			log.Printf("ERROR [security/misconfig] prepare fix: %v", msg.Err)
202			return m, m.footer.Error("Could not prepare the fix — the file may have changed, check logs")
203		}
204		m.misconfigPending = &msg.File
205		m.misconfigFinding = misconfigFindingRef{Rule: msg.Rule, Instance: msg.Instance, File: msg.FindingFile}
206		// Rule 104: the safe answer is the default — ConfirmModal opens on No.
207		m.confirmModal = sharedcomponents.NewConfirmModal("Fix misconfiguration", misconfigConfirmationText(msg.File, msg.Body))
208		return m, nil
209	}
