211	// misconfigConfirmationText shows the diff itself, not a summary of it.
212	//
213	// A base image bump is one token replaced by another and reads as a sentence; a
214	// misconfiguration fix inserts a block, and no sentence conveys what is about to
215	// land in the file. What the user agrees to is the diff, so the diff is what the
216	// modal shows — followed by what git will and will not be able to undo.
217	func misconfigConfirmationText(f preparedWrite, body string) string {
218		return body + "\n" + fmt.Sprintf("%s: %s\n", f.File, gitAdvice(f))
219	}
