221	// handleMisconfigFixConfirmed runs the write the modal was about.
222	func (m Model) handleMisconfigFixConfirmed() (tea.Model, tea.Cmd) {
223		file, ref := m.misconfigPending, m.misconfigFinding
224		m.misconfigPending = nil
225		m.misconfigFinding = misconfigFindingRef{}
226		m.confirmModal = nil
227		if file == nil {
228			return m, nil
229		}
230		return m, writeMisconfigFixCmd(m.targetPath, ref, *file)
231	}
