233	func writeMisconfigFixCmd(target string, ref misconfigFindingRef, f preparedWrite) tea.Cmd {
234		return func() tea.Msg {
235			err := patch.WriteIfUnchanged(f.Path, f.Original, f.Updated)
236			return MisconfigFixWrittenMsg{
237				Target: target, File: f.File, FindingFile: ref.File,
238				Rule: ref.Rule, Instance: ref.Instance, Err: err,
239			}
240		}
241	}
242	
243	// misconfigFindingRef is the finding a pending fix is about, kept between the
244	// confirmation and the write so the verification knows what to look for.
245	type misconfigFindingRef struct {
246		// Rule is the AVD id.
247		Rule string
248		// Instance is which occurrence of it, so a file holding the same rule
249		// twice is not judged by the one the fix did not touch.
250		Instance string
251		// File is where the finding points, which is not always the file written.
252		File string
253	}
254	
255	func (m Model) handleMisconfigFixWritten(msg MisconfigFixWrittenMsg) (tea.Model, tea.Cmd) {
256		if msg.Target != m.targetPath {
257			return m, nil
258		}
259		if msg.Err != nil {
260			cmd := m.reportFailedFix(msg)
261			return m, cmd
262		}
263		// The file changed; the result did not. A re-scan is what turns "written"
264		// into "fixed", so it starts here rather than being left to the user — as a
265		// job, visible in `:jobs` and stoppable with K.
266		v := misconfigVerify{Target: msg.Target, Rule: msg.Rule, File: msg.FindingFile, Instance: msg.Instance}
267		m.misconfigVerifying = &v
268		scan := m.startMisconfigVerification(v)
269		footer := m.footer.Info(fmt.Sprintf("Fixed %s — re-scanning to confirm %s is gone", msg.File, msg.Rule))
270		return m, tea.Batch(scan, footer)
271	}
272	
273	// reportFailedFix sets the footer on the model it is called on, which is why it
274	// takes a pointer: on a copy the message would be set and then thrown away.
275	func (m *Model) reportFailedFix(msg MisconfigFixWrittenMsg) tea.Cmd {
276		if errors.Is(msg.Err, patch.ErrChanged) {
277			return m.footer.Error(fmt.Sprintf("%s changed since the preview — review it again", msg.File))
278		}
279		log.Printf("ERROR [security/misconfig] write %s: %v", msg.File, msg.Err)
280		return m.footer.Error(fmt.Sprintf("Failed to write %s — check logs", msg.File))
281	}
