283	// ── Verifying (§3.78, phase B3) ──────────────────────────────────────────────
284	//
285	// A written file is not a fixed one. The rule that was faulted is still in the
286	// result on screen, because that result was measured before the edit — and the
287	// whole discipline §3.2 set for base images is that a fix is judged by a
288	// re-scan, never by the confidence of whatever produced it. So the write starts
289	// one, and the verdict it reports is binary: the rule is gone, or it is not.
290	//
291	// The scan is an ordinary job (§3.58), which is what makes starting it on the
292	// user's behalf acceptable: it shows up in `:jobs` with a label saying why, and
293	// `K` stops it. Nothing is hidden and nothing is unstoppable.
294	
295	// misconfigVerify is the fix waiting on a re-scan to say whether it worked.
296	type misconfigVerify struct {
297		Target string
298		Rule   string
299		// File is the file the finding points at, where the rule is looked for.
300		File     string
301		Instance string
302	}
303	
304	// MisconfigVerifiedMsg is the verdict: whether the rule the fix was about is
305	// still reported for that file.
306	type MisconfigVerifiedMsg struct {
307		Target  string
308		Rule    string
309		File    string
310		Cleared bool
311		// Result is the scan the verdict was read from, so the tab can stop showing
312		// findings the edit has already dealt with.
313		Result *scan.Result
314		Err    error
315	}
316	
317	// startMisconfigVerification re-scans the target the fix was written into.
318	//
319	// It runs even when the catalog is sure of itself, because being sure is not
320	// the same as having measured — and the cases where a rule survives its own fix
321	// are exactly the ones nobody predicted.
322	func (m Model) startMisconfigVerification(v misconfigVerify) tea.Cmd {
323		if m.scanningTarget(v.Target) {
324			// Something is already measuring this target; its result will answer.
325			return nil
326		}
327		job := inventoryScanJob{Kind: kindRepo, Name: v.Target}
328		opts := m.scanOptions()
329		return jobs.StartInContext(
330			jobs.NewRun(jobs.KindScan, command.ViewSecurity, "", "verify fix", v.Target),
331			func(contextName string) tea.Cmd {
332				return rescanCmd([]inventoryScanJob{job}, opts, contextName)
333			},
334		)
335	}
336	
337	// verifyMisconfigCmd reads the result the re-scan stored and answers whether the
338	// rule is still there. It runs off Update (Rule 110).
339	func verifyMisconfigCmd(v misconfigVerify) tea.Cmd {
340		return func() tea.Msg {
341			result, err := cache.ReadWorkspaceScanResult(v.Target)
342			if err != nil {
343				return MisconfigVerifiedMsg{Target: v.Target, Rule: v.Rule, File: v.File, Err: err}
344			}
345			return MisconfigVerifiedMsg{
346				Target: v.Target, Rule: v.Rule, File: v.File,
347				Cleared: !holdsRule(result, v.Rule, v.File, v.Instance), Result: result,
348			}
349		}
350	}
351	
352	// holdsRule says whether a result still reports this rule for this file —
353	// and, when instance is set, this occurrence of it.
354	//
355	// It matches through remediation.RuleKey rather than on the string, for the
356	// reason the catalog does: Trivy spells one rule two ways, and a comparison
357	// that missed the other spelling would report every fix as successful.
358	//
359	// The occurrence matters for a manifest (§3.80): a Deployment with two
360	// containers is flagged for KSV-0001 twice in one file, and the fix edits one
361	// of them. Judged on the rule and the file alone, the untouched container
362	// would read as the fix having failed.
363	func holdsRule(result *scan.Result, rule, file, instance string) bool {
364		if result == nil {
365			return false
366		}
367		want := remediation.RuleKey(rule)
368		for _, f := range result.Findings {
369			if scan.Categorize(f) != scan.CategoryMisconfiguration {
370				continue
371			}
372			if f.File == file && remediation.RuleKey(f.ID) == want && (instance == "" || instanceOf(f) == instance) {
373				return true
374			}
375		}
376		return false
377	}
378	
379	// instanceOf identifies one occurrence of a rule in a file, without its line,
380	// which the fix itself moves. Trivy words the occurrence in Message ("Container
381	// 'api' of Deployment 'web' should set…"), kubeconform in Title
382	// ("Deployment/web: …"); the pair covers both.
383	func instanceOf(f scan.Finding) string {
384		return f.Title + "\n" + f.Message
385	}
386	
387	// handleMisconfigVerified reports the verdict, and swaps in the result it was
388	// read from.
389	//
390	// The swap is what keeps the screen from contradicting the footer: without it a
391	// line saying the rule is gone would sit above a table still listing it.
392	func (m Model) handleMisconfigVerified(msg MisconfigVerifiedMsg) (tea.Model, tea.Cmd) {
393		if msg.Target != m.targetPath {
394			return m, nil
395		}
396		m.misconfigVerifying = nil
397		if msg.Err != nil {
398			log.Printf("ERROR [security/misconfig] verify %s: %v", msg.Rule, msg.Err)
399			return m, m.footer.Error("Could not read the verification scan — check logs")
400		}
401		if msg.Result != nil {
402			m.setResult(msg.Result)
403		}
404		if !msg.Cleared {
405			// Not a failure: the file was written, and the rule still fires. Saying
406			// so is the only honest answer, and it is why the scan exists.
407			return m, m.footer.Warn(fmt.Sprintf("%s still reported in %s after the fix", msg.Rule, msg.File))
408		}
409		return m, m.footer.Info(fmt.Sprintf("%s cleared in %s — confirmed by a re-scan", msg.Rule, msg.File))
410	}
