22	// Fixing a misconfiguration in place (§3.78, phase B).
23	//
24	// This is the same act as writing a base image (phase C of §3.2) applied to a
25	// second class of finding, so it is the same key, the same confirmation that
26	// defaults to No, and the same write: the bytes at one located range and
27	// nothing else.
28	//
29	// What differs is that only **some** rules can be fixed. The catalog in
30	// internal/remediation is deliberately finite, and a rule outside it is not a
31	// failure — it is the case the MCP server covers by handing a calling agent the
32	// span and the wording. So ctrl+o greys out here far more often than it does on
33	// the Remediation tab, and that greying is what makes the boundary between the
34	// two paths visible instead of guessed at.
35	
36	// ── Reasons (Rule 130) ───────────────────────────────────────────────────────
37	
38	const (
39		reasonNotMisconfigTab = "Built-in fixes belong to the Misconfigurations tab"
40		reasonFileNotOnDisk   = "This target is an image — its files are inside it, not on disk"
41	)
42	
43	// ── Messages (Rule 109) ──────────────────────────────────────────────────────
44	
45	// MisconfigFixPreparedMsg is the answer to computing the fix: the file as it
46	// would become, and what git says about it. It carries the bytes the
47	// confirmation is about, so the write that follows is that one.
48	type MisconfigFixPreparedMsg struct {
49		Target string
50		File   preparedWrite
51		// Rule is the AVD id, which the verification re-scan is checked against.
52		// Body is what the confirmation shows — the fix's title and the diff — and
53		// the two are separate fields because one is read by a human and the other
54		// compared against a later scan.
55		Rule string
56		Body string
57		// Instance says which occurrence of the rule, for the same reason — see
58		// instanceOf.
59		Instance string
60		// FindingFile is the file the finding points at, which the verification
61		// looks in. It is File.File for every rule but the build context's, whose
62		// fix edits the .dockerignore beside the Dockerfile it reports (§3.81).
63		FindingFile string
64		Err         error
65	}
66	
67	// MisconfigFixWrittenMsg reports the write. File is the file written,
68	// FindingFile the one the rule was reported in.
69	type MisconfigFixWrittenMsg struct {
70		Target      string
71		File        string
72		FindingFile string
73		Rule        string
74		Instance    string
75		Err         error
76	}
77	
78	// ── Availability ─────────────────────────────────────────────────────────────
79	
80	// canFixMisconfig is the one computation behind the shortcut column and the
81	// handler (Rule 130). It answers in the order the user would ask: am I in the
82	// right place, is there a row, can its file be written at all, and is this rule
83	// one the catalog knows.
84	//
85	// The last question runs the fix itself. That is deliberate: a rule can be in
86	// the catalog and still decline this instance — a base image whose distribution
87	// cannot be identified, a stage that already sets a user — and greying out on
88	// "the catalog has an entry" while the handler then refuses would be exactly
89	// the two computations Rule 130 forbids.
90	func (m Model) canFixMisconfig() shortcut.Availability {
91		if m.activeTab != TabMisconfig {
92			return shortcut.Unavailable(reasonNotMisconfigTab)
93		}
94		f, ok := m.findingsTable.Selected()
95		if !ok {
96			return shortcut.Unavailable(reasonNoFinding)
97		}
98		if m.result == nil || m.result.TargetType != scan.TargetDirectory {
99			return shortcut.Unavailable(reasonFileNotOnDisk)
100		}
101		if _, ok := remediation.FixFor(f); !ok {
102			return shortcut.Unavailable(noFixReason(f))
103		}
104		// Reading the file here would be I/O on a path the header calls every
105		// frame, so the declines that need the content are left to the Cmd and
106		// reach the footer. What is settled here is everything the finding alone
107		// can answer.
108		return shortcut.Availability{}
109	}
110	
111	// noFixReason is why a finding with no fix in the catalog is refused: for a Pod
112	// Security finding, what the manifest is missing (DEVDESK-689); for anything
113	// else, the generic refusal. The fix is tried first, so a rule that has one never
114	// reaches the missing text.
115	func noFixReason(f scan.Finding) string {
116		if text, ok := remediation.MissingFor(f); ok {
117			return text
118		}
119		return remediation.ReasonNoFixForRule
120	}
121	
122	// ── Preparing ────────────────────────────────────────────────────────────────
123	
124	// prepareMisconfigFix starts the fix by computing it: nothing is asked of the
125	// user until the file has been read, rewritten and put to git, so the
126	// confirmation can state what it is about.
127	func (m Model) prepareMisconfigFix() (tea.Model, tea.Cmd) {
128		if a := m.canFixMisconfig(); !a.Enabled() {
129			return m, m.footer.Warn(a.Reason)
130		}
131		f, _ := m.findingsTable.Selected()
132		return m, prepareMisconfigFixCmd(m.targetPath, f)
133	}
134	
135	// prepareMisconfigFixCmd reads the file, asks the catalog for the edits and
136	// applies them. The finding is copied in (Rule 110).
137	//
138	// A rule that declines here is not an error: it is an answer, and it reaches the
139	// footer as a warning rather than as a failure.
140	func prepareMisconfigFixCmd(target string, f scan.Finding) tea.Cmd {
141		return func() tea.Msg {
142			rule, ok := remediation.FixFor(f)
143			if !ok {
144				return MisconfigFixPreparedMsg{Target: target, Rule: f.ID, Err: errDeclined{noFixReason(f)}}
145			}
146			rel, reason := rule.FileFor(target, f)
147			if reason != "" {
148				return MisconfigFixPreparedMsg{Target: target, Rule: f.ID, Err: errDeclined{reason}}
149			}
150			path := filepath.Join(target, filepath.FromSlash(rel))
151			original, err := readFile(path)
152			if err != nil {
153				return MisconfigFixPreparedMsg{Target: target, Rule: f.ID, Err: err}
154			}
155			edits, reason := rule.Fix(original, f)
156			if reason != "" {
157				return MisconfigFixPreparedMsg{Target: target, Rule: f.ID, Err: errDeclined{reason}}
158			}
159			updated, err := patch.Rewrite(original, edits)
160			if err != nil {
161				return MisconfigFixPreparedMsg{Target: target, Rule: f.ID, Err: fmt.Errorf("%s: %w", rel, err)}
162			}
163			diff, err := patch.Diff(rel, original, edits)
164			if err != nil {
165				return MisconfigFixPreparedMsg{Target: target, Rule: f.ID, Err: fmt.Errorf("%s: %w", rel, err)}
166			}
167			file := preparedWrite{File: rel, Path: path, Original: original, Updated: updated}
168			if file.State, err = git.StateOf(path); err != nil {
169				log.Printf("ERROR [security/misconfig] git state of %s: %v", rel, err)
170				file.StateErr = true
171			}
172			body := rule.Title + "\n\n"
173			if rule.Warning != "" {
174				body += "Warning: " + rule.Warning + "\n\n"
175			}
176			return MisconfigFixPreparedMsg{
177				Target: target, File: file, FindingFile: f.File,
178				Rule: f.ID, Instance: instanceOf(f), Body: body + diff,
179			}
180		}
181	}
